function columnShift(img, frac = 0.2) {
  const { data, bpp, width, height } = img
  const cols = Math.max(1, Math.round(width * frac))
  const acc = (from, to) => {
    const sum = [0, 0, 0]
    let n = 0
    for (let y = 0; y < height; y++) {
      for (let x = from; x < to; x++) {
        const i = (y * width + x) * bpp
        sum[0] += data[i]; sum[1] += data[i + 1]; sum[2] += data[i + 2]; n++
      }
    }
    return sum.map((v) => v / n)
  }
  const left = acc(0, cols)
  const right = acc(width - cols, width)
  return { left: left.map(Math.round), right: right.map(Math.round), delta: Math.round(Math.abs(left[0] - right[0]) + Math.abs(left[2] - right[2])) }
}
