cd /home/ian/hello-world && cat > /tmp/hello-latency.mjs <<'EOF'
import { spawn } from 'node:child_process'
import { mkdtempSync, readFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { pathToFileURL } from 'node:url'
const WORK = mkdtempSync(join(tmpdir(), 'hello-lat-'))
const DATA_FILE = join(WORK, 'hello.json')
const proc = spawn('node', ['main.js'], { cwd: '/home/ian/hello-world', env: { ...process.env, PORT: '3102', DATA_FILE }, stdio: ['ignore','pipe','pipe'] })
await new Promise((r) => proc.stdout.once('data', r))
const mod = await import(pathToFileURL('/home/ian/.local/share/mise/installs/npm-playwright/1.63.0/node_modules/playwright/index.js').href)
const { chromium } = mod.default ?? mod
const browser = await chromium.launch({ headless: true, executablePath: '/home/ian/.cache/ms-playwright/chromium-1228/chrome-linux64/chrome' })
const page = await (await browser.newContext()).newPage()
await page.goto('http://127.0.0.1:3102', { waitUntil: 'load' })
await page.waitForFunction(() => (document.querySelector('#status')?.textContent ?? '').includes('Type to edit'), null, { polling: 50 })
await page.click('#text'); await page.keyboard.press('Control+a')
const t0 = Date.now()
await page.keyboard.type('latency probe')
const target = await page.textContent('#text')
while (readFileSync(DATA_FILE, 'utf8') !== target) { if (Date.now() - t0 > 5000) throw new Error('never persisted') ; await new Promise(r => setTimeout(r, 5)) }
const ms = Date.now() - t0
console.log(`last keystroke -> "${target}" present in ${DATA_FILE.replace(WORK, '<tmp>')} : ${ms} ms (target <= 1000 ms incl. typing time)`)
const afterLast = await page.evaluate(() => null) ?? null
console.log(`status text after save: ${await page.textContent('#status')}`)
await browser.close(); proc.kill('SIGTERM'); rmSync(WORK, { recursive: true, force: true })
console.log(ms <= 1000 ? 'A3 LATENCY: PASS' : 'A3 LATENCY: FAIL')
EOF
timeout 120 node /tmp/hello-latency.mjs; echo "exit=$?"; ss -ltn | grep 3102 || echo "3102 released"

