import { readFileSync } from 'node:fs'
import zlib from 'node:zlib'
function decodePng(buf) {
  let pos = 8, width = 0, height = 0, colorType = 0
  const idat = []
  while (pos < buf.length) {
    const len = buf.readUInt32BE(pos), type = buf.toString('ascii', pos + 4, pos + 8)
    const data = buf.subarray(pos + 8, pos + 8 + len)
    if (type === 'IHDR') { width = data.readUInt32BE(0); height = data.readUInt32BE(4); colorType = data[9] }
    else if (type === 'IDAT') idat.push(data)
    else if (type === 'IEND') break
    pos += 12 + len
  }
  const bpp = colorType === 6 ? 4 : 3, stride = width * bpp
  const raw = zlib.inflateSync(Buffer.concat(idat)), out = Buffer.alloc(height * stride)
  const paeth = (a, b, c) => { const p = a + b - c, pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c); return pa <= pb && pa <= pc ? a : pb <= pc ? b : c }
  for (let y = 0; y < height; y++) {
    const src = y * (stride + 1), filter = raw[src], row = raw.subarray(src + 1, src + 1 + stride)
    const cur = y * stride, prev = (y - 1) * stride
    for (let x = 0; x < stride; x++) {
      const a = x >= bpp ? out[cur + x - bpp] : 0, b = y > 0 ? out[prev + x] : 0, c = x >= bpp && y > 0 ? out[prev + x - bpp] : 0, v = row[x]
      out[cur + x] = filter === 0 ? v : filter === 1 ? v + a : filter === 2 ? v + b : filter === 3 ? v + ((a + b) >> 1) : v + paeth(a, b, c)
    }
  }
  return { width, height, bpp, data: out }
}
for (const f of process.argv.slice(2)) {
  const img = decodePng(readFileSync(f))
  const colours = new Set(); let bright = 0; const sum = [0,0,0]; let n = 0
  for (let i = 0; i < img.data.length; i += img.bpp) {
    const [r,g,b] = [img.data[i], img.data[i+1], img.data[i+2]]
    colours.add((r >> 3 << 10) | (g >> 3 << 5) | (b >> 3))
    if (0.2126*r + 0.7152*g + 0.0722*b > 140) bright++
    sum[0]+=r; sum[1]+=g; sum[2]+=b; n++
  }
  console.log(`${f}: ${img.width}x${img.height} distinct=${colours.size} brightPx=${bright} (${(bright/n*100).toFixed(1)}%) mean=${sum.map(v=>Math.round(v/n)).join(',')} nonBlack=${(bright/n*100) > 0.5 ? 'content present' : 'SUSPECT BLANK'}`)
}
EOF
