async function statusIs(page, prefix, timeout = 2000) {
  // polling by timer, not rAF: rAF is throttled for backgrounded headless pages
  try {
    await page.waitForFunction(
      (p) => (document.querySelector('#status')?.textContent ?? '').startsWith(p),
      prefix,
      { timeout, polling: 50 },
    )
  } catch (error) {
    const now = await page.evaluate(() => ({
      status: document.querySelector('#status')?.textContent,
      text: document.querySelector('#text')?.textContent,
      ready: document.readyState,
    }))
    throw new Error(`status never reached "${prefix}" — ${JSON.stringify(now)} (${error.message})`)
  }
}

