}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  height: 100%;
}

body {
  min-height: 100svh;
  display: grid;
  place-items: center;
  overflow: hidden;
  margin: 0;
  font-family: ui-rounded, system-ui, -apple-system, "Segoe UI", Inter, sans-serif;
  color: var(--text-soft);
  background: var(--bg-deep);
}

/* ---- layered background: base gradient, aurora blobs, grain + vignette ---- */

.bg,
.aurora,
.grain {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: -1;
}

.bg {
  background:
    radial-gradient(120% 85% at 50% 20%, var(--bg-glow) 0%, var(--bg-mid) 62%, var(--bg-mid) 100%),
    linear-gradient(165deg, #0b0d1c 0%, var(--bg-deep) 100%);
}

.aurora {
  overflow: hidden;
  mix-blend-mode: screen;
}

.blob {
  position: absolute;
  display: block;
  width: 46vmax;
  height: 46vmax;
  border-radius: 50%;
  filter: blur(90px);
  opacity: 0.5;
  mix-blend-mode: screen;
  will-change: transform;
}

.blob-violet {
  top: -14vmax;
  left: -10vmax;
  background: var(--violet);
  animation: drift-violet 24s ease-in-out infinite alternate;
}

.blob-cyan {
  bottom: -18vmax;
  right: -8vmax;
  background: var(--cyan);
  animation: drift-cyan 33s ease-in-out infinite alternate;
}

.blob-magenta {
  top: 24vmax;
  right: 26vmax;
  background: var(--magenta);
  animation: drift-magenta 41s ease-in-out infinite alternate;
}

@keyframes drift-violet {
  from {
    transform: translate3d(0, 0, 0) scale(1);
  }
  to {
    transform: translate3d(14vmax, 8vmax, 0) scale(1.25);
  }
}

@keyframes drift-cyan {
  from {
    transform: translate3d(0, 0, 0) scale(1.1);
  }
  to {
    transform: translate3d(-16vmax, -10vmax, 0) scale(0.9);
  }
}

@keyframes drift-magenta {
  from {
    transform: translate3d(0, 0, 0) scale(0.95);
  }
  to {
    transform: translate3d(-10vmax, 12vmax, 0) scale(1.2);
  }
}

.grain::before,
.grain::after {
  content: "";
  position: absolute;
  inset: 0;
}

.grain::before {
  background-image: var(--grain);
  opacity: 0.05;
}

.grain::after {
  background: radial-gradient(circle at 50% 50%, transparent 45%, rgba(0, 0, 0, 0.55) 100%);
}

/* ---- headline ---- */

main {
  width: min(1100px, 92vw);
  text-align: center;
  padding: clamp(1rem, 6vw, 4rem);
}

#text {
  margin: 0;
  font-size: clamp(3rem, 12vw, 11rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 0.95;
  white-space: pre-wrap;
  overflow-wrap: break-word;
  cursor: text;
  caret-color: #fff;
  background-image: linear-gradient(100deg, #ffffff, #b7c3ff 35%, #7dd3fc 70%, #f0abfc);
  background-size: 220% 100%;
  background-position: 0% 50%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  filter: drop-shadow(0 0 40px rgba(125, 211, 252, 0.35));
  animation: shimmer 12s ease-in-out infinite alternate;
  outline-offset: 0.2em;
  border-radius: 0.1em;
}

#text::selection {
  background: rgba(125, 211, 252, 0.35);
  -webkit-text-fill-color: #f8fbff;
}

#text:focus {
  outline: 2px solid rgba(125, 211, 252, 0.55);
  outline-offset: 0.15em;
}

#text:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 0.2em;
  border-radius: 0.1em;
}

@keyframes shimmer {
  from {
    background-position: 0% 50%;
  }
  to {
    background-position: 100% 50%;
  }
}

#text.saved {
  animation:
    shimmer 12s ease-in-out infinite alternate,
    brighten 1.2s ease;
}

@keyframes brighten {
  0%,
  100% {
    filter: drop-shadow(0 0 40px rgba(125, 211, 252, 0.35));
  }
  40% {
    filter: brightness(1.25) drop-shadow(0 0 60px rgba(125, 211, 252, 0.6));
  }
}

/* ---- status pill ---- */

.status {
  position: fixed;
  bottom: clamp(1rem, 5vh, 3rem);
  left: 50%;
  transform: translateX(-50%);
  margin: 0;
  display: inline-flex;
  align-items: center;
  gap: 0.6em;
  padding: 0.5em 1.1em;
  border: 1px solid rgba(219, 227, 255, 0.22);
  border-radius: 999px;
  background: rgba(6, 8, 20, 0.72);
  color: var(--text-soft);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  white-space: nowrap;
  opacity: 0.75;
  transition: opacity 0.3s ease;
}

.status::before {
  content: "";
  width: 0.55em;
  height: 0.55em;
  border-radius: 50%;
  background: #8b96c4;
}

.status.saving,
.status.saved,
.status.error {
  opacity: 1;
}

.status.saving::before {
  background: #fcd34d;
}

.status.saved::before {
  background: #34d399;
}

.status.error::before {
  background: #f87171;
}

.status.saved {
  animation: pulse 1.2s ease;
}

@keyframes pulse {
  0%,
  100% {
    transform: translateX(-50%) scale(1);
  }
  45% {
    transform: translateX(-50%) scale(1.07);
  }
}

noscript p {
  margin-top: 2rem;
  font-size: 0.9rem;
  letter-spacing: 0.08em;
}

/* ---- responsive ---- */

@media (max-width: 640px) {
  .blob {
    filter: blur(50px);
  }
}

/* ---- reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
  }
}

