  cursor: text;
  caret-color: #fff;
  background-image: linear-gradient(100deg, #ffffff, #b7c3ff 35%, #7dd3fc 70%, #f0abfc);
  background-size: 220% 100%;
  background-position: 0% 50%;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  filter: drop-shadow(0 0 40px rgba(125, 211, 252, 0.35));
  animation: shimmer 12s ease-in-out infinite alternate;
  outline-offset: 0.2em;
  border-radius: 0.1em;
}

#text::selection {
  background: rgba(125, 211, 252, 0.35);
  -webkit-text-fill-color: #f8fbff;
}

#text:focus {
  outline: 2px solid rgba(125, 211, 252, 0.55);
  outline-offset: 0.15em;
}

#text:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 0.2em;
  border-radius: 0.1em;
}

@keyframes shimmer {
  from {
    background-position: 0% 50%;
  }
  to {
    background-position: 100% 50%;
  }
}

#text.saved {
  animation:
    shimmer 12s ease-in-out infinite alternate,
    brighten 1.2s ease;
}

@keyframes brighten {
  0%,
  100% {
    filter: drop-shadow(0 0 40px rgba(125, 211, 252, 0.35));
  }
  40% {
    filter: brightness(1.25) drop-shadow(0 0 60px rgba(125, 211, 252, 0.6));
  }
}

/* ---- status pill ---- */

.status {
  position: fixed;
  bottom: clamp(1rem, 5vh, 3rem);
  left: 50%;
  transform: translateX(-50%);
  margin: 0;
  display: inline-flex;
  align-items: center;
  gap: 0.6em;
  padding: 0.5em 1.1em;
  border: 1px solid rgba(219, 227, 255, 0.22);
  border-radius: 999px;
  background: rgba(6, 8, 20, 0.72);
  color: var(--text-soft);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  white-space: nowrap;
  opacity: 0.75;
  transition: opacity 0.3s ease;
}

.status::before {
  content: "";
  width: 0.55em;
  height: 0.55em;
  border-radius: 50%;
  background: #8b96c4;
}

.status.saving,
.status.saved,
.status.error {
  opacity: 1;
}

.status.saving::before {
  background: #fcd34d;
}

.status.saved::before {
  background: #34d399;
}

.status.error::before {
  background: #f87171;
}

.status.saved {
  animation: pulse 1.2s ease;
}

@keyframes pulse {
  0%,
  100% {
    transform: translateX(-50%) scale(1);
  }
  45% {
